/// 内存缓存：painter 每帧调用，解析结果复用（null 也缓存）。
final Map<String, ModelSilhouette?> _cache = <String, ModelSilhouette?>{};

/// 查表构造轮廓；缺条目 / 解析失败 → null（画布回落 RRect）。
ModelSilhouette? silhouetteFor(String? modelId) {
  if (modelId == null) return null;
  if (_cache.containsKey(modelId)) return _cache[modelId];
  final raw = modelSilhouettes[modelId];
  ModelSilhouette? out;
  if (raw != null) {
    try {
      out = ModelSilhouette.fromJson(raw);
    } catch (_) {
      out = null;
    }
  }
  _cache[modelId] = out;
  return out;
}
